def departures(edge, arrival, coupons_left):
    depart = max(arrival, edge["open"])
    # Departure must be strictly before the edge's closing time.
    if depart >= edge["close"]:
        return []

    choices = [(depart + edge["duration"], coupons_left)]
    if coupons_left > 0:
        duration = max(
            POLICY["minimum_duration"],
            edge["duration"] - edge.get("discount", 0),
        )
        choices.append((depart + duration, coupons_left - 1))
    return choices


def visit_mask(node, required):
    mask = 0
    for index, name in enumerate(required):
        if node == name:
            mask |= 1 << index
    return mask
